std::string msg = status->error_message();
// Lightly consume the string to cover small/empty/non-empty cases
if (!msg.empty()) { (void)msg[0]; }
// Preserve the object for reuse
// Validation: Non-mutating accessor called; the input Status is returned to the pool.

// Access the stored status code
gs::StatusCode code = status->error_code();
// Record a derived attribute for downstream checks
FUZZ_SET_ATTR_INT(status, "is_ok", (code == gs::flex::interactive::Code::OK) ? 1 : 0);
(void)code;
// Validation: Non-mutating accessor executed; object state hint is updated via attributes and object is preserved.

