FUZZ_ASSERT(status->ok(), "Status::OK must be ok()");
FUZZ_SET_ATTR_INT(status, "is_ok", 1);
// Validation: A new persistent gs::Status* is created from the factory result; property is asserted.

// Convert the status to a human-readable string representation
